import { forwardRef, memo } from "preact/compat";
import { t } from "./lib/i18n.js";

const CREST_SHAPES = [
    "M2 1h12v7c0 4-3 6-6 7-3-1-6-3-6-7z",
    "M1 2h14l-2 8-5 5-5-5z",
    "M8 1l7 3v5c0 3-3 5-7 6-4-1-7-3-7-6V4z",
    "M3 1h10v9l-5 5-5-5z",
];

export const Crest = memo(function Crest({ crest }) {
    return (
        <svg class="sov-crest" viewBox="0 0 16 16" width="20" height="20" aria-hidden="true" focusable="false">
            <path d={CREST_SHAPES[crest.shape % CREST_SHAPES.length]} fill={crest.primary} stroke={crest.secondary} stroke-width="1.2" />
        </svg>
    );
});

export const MatchRow = memo(function MatchRow({ match }) {
    return (
        <li class="sov-match" data-status={match.status}>
            <a class="sov-match__link" href={match.href} aria-label={match.label}>
                <time class="sov-match__time" dateTime={match.iso}>{match.when}</time>
                <span class="sov-team sov-team--home">
                    <Crest crest={match.home.crest} />
                    <span class="sov-team__name">{match.home.name}</span>
                </span>
                <span class="sov-score">
                    <span class="sov-score__goals">{match.homeGoals}</span>
                    <span class="sov-score__sep">:</span>
                    <span class="sov-score__goals">{match.awayGoals}</span>
                </span>
                <span class="sov-team sov-team--away">
                    <span class="sov-team__name">{match.away.name}</span>
                    <Crest crest={match.away.crest} />
                </span>
                <span class="sov-match__status">{match.statusText}</span>
                <span class="sov-match__ht">{match.halftime}</span>
            </a>
        </li>
    );
});

export const CompactRow = memo(function CompactRow({ match }) {
    return (
        <li class="sov-compact">
            <a class="sov-compact__link" href={match.href} aria-label={match.label}>
                <time class="sov-compact__time" dateTime={match.iso}>{match.when}</time>
                <span class="sov-compact__team">{match.home.shortName}</span>
                <span class="sov-compact__score">
                    <span>{match.homeGoals}</span>
                    <span>{match.awayGoals}</span>
                </span>
                <span class="sov-compact__team">{match.away.shortName}</span>
            </a>
        </li>
    );
});

const Chevron = ({ direction }) => (
    <svg class="sov-chevron" viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
        <path d={direction === "left" ? "M10 3 5 8l5 5" : direction === "right" ? "M6 3l5 5-5 5" : "M3 6l5 5 5-5"} fill="none" stroke="currentColor" stroke-width="2" />
    </svg>
);

export const Tab = memo(function Tab({ competition, selected, onSelect }) {
    return (
        <button class="sov-tab" type="button" role="tab" id={`sov-tab-${competition.id}`} aria-selected={selected ? "true" : "false"} aria-controls="sov-panel" tabIndex={selected ? 0 : -1} data-tone={competition.tone} onClick={() => onSelect(competition.id)}>
            {competition.shortName}
        </button>
    );
});

export const MatchdayNav = forwardRef(function MatchdayNav({ number, range, loading, canGoBack, canGoForward, onStep }, ref) {
    return (
        <div class="sov-nav" ref={ref} aria-busy={loading ? "true" : "false"}>
            <button class="sov-nav__button" type="button" aria-label={t("overview.previous")} disabled={!canGoBack} onClick={() => onStep(-1)}>
                <Chevron direction="left" />
            </button>
            <span class="sov-nav__label" aria-live="polite">{`${t("overview.matchday", { number })} (${range})`}</span>
            <button class="sov-nav__button" type="button" aria-label={t("overview.next")} disabled={!canGoForward} onClick={() => onStep(1)}>
                <Chevron direction="right" />
            </button>
        </div>
    );
});

export const Standings = memo(function Standings({ rows }) {
    return (
        <section class="sov-standings" aria-label={t("overview.standings")}>
            <h3 class="sov-standings__title">{t("overview.standings")}</h3>
            <table class="sov-table">
                <thead>
                    <tr>
                        <th scope="col">{t("overview.rank")}</th>
                        <th scope="col">{t("overview.team")}</th>
                        <th scope="col">{t("overview.played")}</th>
                        <th scope="col">{t("overview.points")}</th>
                    </tr>
                </thead>
                <tbody>
                    {rows.map((row) => (
                        <tr key={row.id}>
                            <td>{row.rank}</td>
                            <td>{row.name}</td>
                            <td>{row.played}</td>
                            <td>{row.points}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </section>
    );
});

export const CompetitionBlock = memo(function CompetitionBlock({ competition, matches }) {
    return (
        <li class="sov-block" data-tone={competition.tone}>
            <h3 class="sov-block__title">
                <a href={`/sport/${competition.slug}`}>{competition.name}</a>
            </h3>
            <ul class="sov-compact-list">
                {matches.map((match) => (
                    <CompactRow key={match.id} match={match} />
                ))}
            </ul>
        </li>
    );
});

export const ExpandButton = memo(function ExpandButton({ expanded, onToggle }) {
    return (
        <div class="sov-more">
            <button class="sov-more__button" type="button" aria-label={t("overview.more")} aria-expanded={expanded ? "true" : "false"} aria-controls="sov-blocks" onClick={onToggle}>
                <span>{t("overview.moreText")}</span>
                <Chevron direction="down" />
            </button>
        </div>
    );
});
