import { useMemo } from "preact/hooks";
import { useParsedData, useWidgetEvents } from "../../shared/lib/lifecycle.js";
import { useStore } from "../../shared/lib/store.js";
import { createOverviewStore } from "./lib/state.js";
import { groupByDay, normalizeOverview } from "./lib/normalize.js";
import { t } from "./lib/i18n.js";
import { CompetitionBlock, ExpandButton, MatchdayNav, MatchRow, Standings, Tab } from "./components.js";

export const TAG = "np-scores-overview";

function Overview({ model }) {
    const controller = useMemo(() => createOverviewStore(model), [model]);
    const { store } = controller;
    const activeId = useStore(store, (state) => state.activeId);
    const expanded = useStore(store, (state) => state.expanded);
    const loading = useStore(store, (state) => state.loading);
    const revision = useStore(store, (state) => state.revision);
    const matchdays = store.getState().matchdays;
    const ref = useWidgetEvents(TAG, revision);

    const active = model.competitions.find((competition) => competition.id === activeId);
    const activeDay = matchdays[activeId];
    const tabs = model.competitions.filter((competition) => competition.isTab);
    const others = model.competitions.filter((competition) => competition.id !== activeId);
    const visible = expanded ? others : others.slice(0, model.collapsedCount);

    return (
        <div class="sov-root" data-variant={model.variant} data-loading={loading ? "true" : "false"} ref={ref}>
            <header class="sov-header">
                <h2 class="sov-title">{t("overview.title")}</h2>
                <a class="sov-all" href="/sport/ergebnisse">{t("overview.allLink")}</a>
            </header>
            <div class="sov-tabs" role="tablist" aria-label={t("overview.tabs")}>
                {tabs.map((competition) => (
                    <Tab key={competition.id} competition={competition} selected={competition.id === activeId} onSelect={controller.selectCompetition} />
                ))}
            </div>
            <div class="sov-panel" id="sov-panel" role="tabpanel" aria-labelledby={`sov-tab-${activeId}`}>
                <MatchdayNav
                    number={activeDay.number}
                    range={activeDay.range}
                    loading={loading}
                    canGoBack={activeDay.number > model.range.min}
                    canGoForward={activeDay.number < model.range.max}
                    onStep={controller.stepMatchday}
                />
                <ul class="sov-matches">
                    {groupByDay(activeDay.matches).flatMap((group) => [
                        <li class="sov-day" key={group.key}>{group.label}</li>,
                        ...group.matches.map((match) => <MatchRow key={match.id} match={match} />),
                    ])}
                </ul>
                {active.standings ? <Standings rows={active.standings} /> : null}
            </div>
            <ul class="sov-blocks" id="sov-blocks" data-expanded={expanded ? "true" : "false"}>
                {visible.map((competition) => (
                    <CompetitionBlock key={competition.id} competition={competition} matches={matchdays[competition.id].matches.slice(0, competition.isTab ? 8 : 3)} />
                ))}
            </ul>
            <ExpandButton expanded={expanded} onToggle={controller.toggleExpanded} />
        </div>
    );
}

export function Widget({ dataJson }) {
    const data = useParsedData(dataJson);
    const model = useMemo(() => (data ? normalizeOverview(data) : null), [data]);
    return model ? <Overview model={model} /> : null;
}
