export const schemas = {
    CompetitionOverview: {
        typename: "CompetitionOverview",
        fields: { id: "string", variant: "string", now: "timestamp", activeCompetitionId: "string", tabCount: "number", collapsedCount: "number", matchdayRange: "MatchdayRange", competitions: "CompetitionConnection" },
    },
    MatchdayRange: { typename: "MatchdayRange", fields: { min: "number", max: "number", current: "number" } },
    CompetitionConnection: { typename: "CompetitionConnection", fields: { totalCount: "number", edges: "[CompetitionEdge]" } },
    CompetitionEdge: { typename: "CompetitionEdge", fields: { cursor: "string", node: "Competition" } },
    Competition: {
        typename: "Competition",
        fields: { id: "string", slug: "string", name: "string", shortName: "string", tier: "number", season: "Season", country: "Country", matchdayCount: "number", teamCount: "number", tone: "number", currentMatchday: "Matchday", standings: "Standings?" },
    },
    Season: { typename: "Season", fields: { id: "string", label: "string" } },
    Country: { typename: "Country", fields: { code: "string", name: "string" } },
    Matchday: { typename: "Matchday", fields: { id: "string", number: "number", startsAt: "timestamp", endsAt: "timestamp", matches: "[Match]" } },
    Match: { typename: "Match", fields: { id: "string", kickoff: "timestamp", status: "string", homeTeam: "Team", awayTeam: "Team", score: "Score?" } },
    Team: { typename: "Team", fields: { id: "string", name: "string", shortName: "string", crest: "Crest?" } },
    Crest: { typename: "Crest", fields: { primary: "string", secondary: "string", shape: "number" } },
    Score: { typename: "Score", fields: { home: "number", away: "number", halftime: "HalftimeScore" } },
    HalftimeScore: { typename: "HalftimeScore", fields: { home: "number", away: "number" } },
    Standings: { typename: "Standings", fields: { rows: "[StandingRow]" } },
    StandingRow: { typename: "StandingRow", fields: { rank: "number", team: "Team", played: "number", points: "number" } },
};
