import { useEffect, useMemo, useRef } from "preact/hooks";

export function parseDataJson(dataJson) {
    if (!dataJson)
        return null;
    try {
        return JSON.parse(dataJson);
    } catch (error) {
        console.error("[widget] invalid data-json", error);
        return null;
    }
}

export function useParsedData(dataJson) {
    return useMemo(() => parseDataJson(dataJson), [dataJson]);
}

// Dispatches widget-ready after the first commit and widget-updated after each
// later one; `revision` changes whenever an interaction re-renders the widget.
export function useWidgetEvents(tag, revision = 0) {
    const ref = useRef(null);
    const ready = useRef(false);
    useEffect(() => {
        const element = ref.current?.closest(tag);
        if (!element)
            return;
        if (!ready.current) {
            ready.current = true;
            element.dispatchEvent(new CustomEvent("widget-ready", { bubbles: true }));
            window.__benchmarkWork?.settled(`widget:${tag}`);
        } else {
            element.dispatchEvent(new CustomEvent("widget-updated", { bubbles: true }));
        }
    }, [revision]);
    return ref;
}
