import { assertValid, unwrapConnection } from "../../../shared/lib/validate.js";
import { dayKey, formatLongDate, formatShortDate, formatTime, formatWeekday } from "../../../shared/lib/format.js";
import { schemas } from "./schema.js";
import { t } from "./i18n.js";

export function normalizeMatch(match) {
    const kickoff = Date.parse(match.kickoff);
    const finished = match.status === "FINISHED";
    const score = match.score;
    return {
        id: match.id,
        kickoff,
        dayKey: dayKey(kickoff),
        dayLabel: formatLongDate(kickoff),
        iso: match.kickoff,
        when: `${formatWeekday(kickoff)} ${formatTime(kickoff)}`,
        status: match.status,
        statusText: finished ? t("overview.finished") : match.status === "LIVE" ? t("overview.live") : t("overview.preview"),
        home: match.homeTeam,
        away: match.awayTeam,
        homeGoals: score ? String(score.home) : t("overview.noScore"),
        awayGoals: score ? String(score.away) : t("overview.noScore"),
        halftime: score ? t("overview.halftime", { home: score.halftime.home, away: score.halftime.away }) : "",
        href: `/sport/spiel/${match.id}`,
        label: score
            ? t("overview.resultLabel", { home: match.homeTeam.name, away: match.awayTeam.name, homeGoals: score.home, awayGoals: score.away })
            : t("overview.matchLabel", { home: match.homeTeam.name, away: match.awayTeam.name, when: `${formatWeekday(kickoff)} ${formatTime(kickoff)}` }),
    };
}

export function normalizeMatchday(matchday, full) {
    return {
        number: matchday.number,
        full,
        range: `${formatShortDate(Date.parse(matchday.startsAt))} - ${formatShortDate(Date.parse(matchday.endsAt))}`,
        matches: matchday.matches.map(normalizeMatch),
    };
}

export function normalizeOverview(raw) {
    assertValid(schemas, "CompetitionOverview", raw);
    const competitions = unwrapConnection(raw.competitions).map((node, index) => ({
        id: node.id,
        slug: node.slug,
        name: node.name,
        shortName: node.shortName,
        tone: node.tone,
        season: node.season.label,
        matchdayCount: node.matchdayCount,
        isTab: index < raw.tabCount,
        standings: node.standings ? node.standings.rows.map((row) => ({ rank: row.rank, id: row.team.id, name: row.team.name, played: row.played, points: row.points })) : null,
        initialMatchday: normalizeMatchday(node.currentMatchday, node.id === raw.activeCompetitionId),
    }));
    return {
        id: raw.id,
        variant: raw.variant,
        now: Date.parse(raw.now),
        activeId: raw.activeCompetitionId,
        collapsedCount: raw.collapsedCount,
        range: raw.matchdayRange,
        competitions,
    };
}

export function groupByDay(matches) {
    const groups = [];
    for (const match of matches) {
        const last = groups[groups.length - 1];
        if (last && last.key === match.dayKey)
            last.matches.push(match);
        else
            groups.push({ key: match.dayKey, label: match.dayLabel, matches: [match] });
    }
    return groups;
}
