import { createStore } from "../../../shared/lib/store.js";
import { fetchJson } from "../../../shared/lib/fetcher.js";
import { normalizeMatchday } from "./normalize.js";

const API = "data/api/widgets/scores";

export function createOverviewStore(model) {
    const matchdays = {};
    for (const competition of model.competitions)
        matchdays[competition.id] = competition.initialMatchday;
    const store = createStore({ activeId: model.activeId, expanded: false, loading: false, matchdays, revision: 0 });
    let requestToken = 0;

    async function loadMatchday(competitionId, number) {
        const token = ++requestToken;
        store.setState({ loading: true });
        try {
            const payload = await fetchJson(`${API}/${competitionId}/matchday-${number}.json`);
            if (token !== requestToken)
                return;
            const next = normalizeMatchday(payload.matchday, true);
            store.setState((state) => ({ loading: false, matchdays: { ...state.matchdays, [competitionId]: next }, revision: state.revision + 1 }));
        } catch (error) {
            console.error("[np-scores-overview] could not load matchday", error);
            if (token === requestToken)
                store.setState({ loading: false });
        }
    }

    return {
        store,
        selectCompetition(id) {
            const state = store.getState();
            if (id === state.activeId)
                return;
            store.setState({ activeId: id, revision: state.revision + 1 });
            const matchday = store.getState().matchdays[id];
            if (!matchday.full)
                loadMatchday(id, matchday.number);
        },
        stepMatchday(delta) {
            const state = store.getState();
            const current = state.matchdays[state.activeId];
            const target = current.number + delta;
            if (target < model.range.min || target > model.range.max)
                return;
            loadMatchday(state.activeId, target);
        },
        toggleExpanded() {
            store.setState((state) => ({ expanded: !state.expanded, revision: state.revision + 1 }));
        },
    };
}
